/* w1: Realm data, ported from Terra Chimera's DB: regions, tiles, locations, towns, dungeons, NPCs, events, cups, recipes */
/* Not ported: species, parts, uniques, muts, trees, moves, rare, rumours, the type tables (MT ST LK PT UT), dmgTypes, passRules,
   battleRange, encounters, encountersNight, the geneticist, and TC's editor DEFAULTS. dropped everywhere: research data
   (giveRp, rp, rpTeam), part and egg rewards, snares, mutagen, purge, and battle items. */
const mulberry=(a)=>()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296};
function hash2(x,y,s){let h=(Math.imul(x|0,374761393)+Math.imul(y|0,668265263)+Math.imul((s|0)+7,1442695041))|0;h=Math.imul(h^(h>>>13),1274126177);return((h^(h>>>16))>>>0)/4294967296}
function noise2(seed){const r=mulberry(seed),N=32,gr=[];for(let i=0;i<N*N;i++)gr.push(r());const at=(x,y)=>gr[((y%N+N)%N)*N+((x%N+N)%N)];return(x,y,s)=>{x/=s;y/=s;const x0=Math.floor(x),y0=Math.floor(y),fx=x-x0,fy=y-y0,sx=fx*fx*(3-2*fx),sy=fy*fy*(3-2*fy);return(at(x0,y0)*(1-sx)+at(x0+1,y0)*sx)*(1-sy)+(at(x0,y0+1)*(1-sx)+at(x0+1,y0+1)*sx)*sy}}
/* TC's weighted pick over [{w:..}] (events). SD's wpick takes {key:weight}: use wpick(Object.fromEntries(region.sports)) for sports. */
function wWpick(list,rng){let t=0;for(const e of list)t+=e.w;let r=(rng||Math.random)()*t;for(const e of list){r-=e.w;if(r<=0)return e}return list[list.length-1]}
