/* road events (phase 4): rolled on the overworld from the encounter hook (w9-road.js), weighted by w. Each opens an
   event card. A choice may cost (cost: gold, items, hp) and pays effects:
     gold (n or [lo, hi]), fans, items, energy { here | elem: n or [lo, hi] }, time (minutes), healPct, steal (an item),
     snack (a meal id into your bag), charm (a fortune for the next match), practice / upgrade (pick a card), lore,
     card / cards / cardChoice (wGainCard), chance + fail (a gamble), match { type, name, win } (a match: kind 'event').
   time: 'day' | 'night' only then; region: [ids] only there; need: a flag. By day on a road, nothing that starts a match.
   Kept from TC (rewritten for teams): pedlar, purse, rival, shed, cook, lostchild, maud, oriel, moth, poacher, wisp, thief.
   dropped: stray and egg (snaring and eggs are cut), inspector (snares), storm (only lost time), scholar, bard and soto
   (they paid research data), drover (salves have no use yet), race (one creature's speed), and the four region
   traders nephew, fisher, miner and pilgrim (the region shops sell the same food). */
DB.events=[
 {id:'pedlar',w:4,who:{name:'Tamsin Crook, pedlar',kind:'goblin'},text:'A pedlar with a cart of jars flags you down. "Pies, handler? Grain? Everything fresh this week, or this month, anyway."',choices:[{label:'A Trail Hash to take away (14 gold)',cost:{gold:14},snack:'hash',result:'She wraps it in newspaper. "Eat it before the game, not after."'},{label:'Grain and salt for the pot (10 gold)',cost:{gold:10},items:{grain:2,salt:2},result:'"Do not eat it raw. People do."'}]},
 {id:'purse',w:3,who:{scene:'purse'},text:'Somebody\'s purse lies in the road, dropped from a wagon. There is nobody in sight.',choices:[{label:'Keep it',gold:[15,45],result:'Finders keepers.'},{label:'Hand it in at the next League post',fans:15,result:'A clerk is pleased. Word gets round that your team plays fair.'}]},
 {id:'rival',w:3,who:{rival:1},text:'A rival club\'s wagon is drawn up at the crossroads. "Friendly match? Loser buys the next round, and the winner takes the purse."',choices:[{label:'Accept the match',match:{type:'normal',win:{gold:[35,50],fans:20},winText:'They pay up with bad grace.'}}]},
 {id:'shed',w:3,who:{scene:'shed'},text:'A well by the road has cracked, and shards of raw energy glitter in the grass round it.',auto:{energy:{here:[2,4]}}},
 {id:'cook',w:3,who:{name:'Barnaby Stew, road cook',kind:'ogre'},text:'A travelling cook stirs a pot on a tripod by the road. It smells of pepper and good intentions.',choices:[{label:'A hot meal for the team now (15 gold)',cost:{gold:15},healPct:.3,result:'Everyone eats. Everyone feels better.'},{label:'A pot of chili to go (20 gold)',cost:{gold:20},snack:'chili',result:'"Eat it before kickoff. It bites back."'}]},
 {id:'lostchild',w:2,time:'day',who:{name:'Wren, aged eight',kind:'kobold'},text:'A child is calling into the grass for her pet, a Mossprout called Biscuit. "He always comes back. He always comes back."',choices:[{label:'Help look (an hour)',time:60,gold:25,fans:10,result:'You find Biscuit asleep under a hedge. Her mother presses coins on you and will not take them back.'}]},
 {id:'maud',w:2,who:{name:'Old Maud Kerry, retired coach',kind:'dwarf'},text:'An old coach leans on a stick by the milestone. "Your forwards stand wrong. I could fix that, for the price of a pie."',choices:[{label:'A practice session (40 gold, 90 minutes)',cost:{gold:40},time:90,practice:1,result:'She drills one play until it is second nature.'},{label:'Watch film with her (60 gold, 2 hours)',cost:{gold:60},time:120,upgrade:1,result:'She stops the tape every four seconds. It helps.'}]},
 {id:'oriel',w:2,who:{name:'Madame Oriel',kind:'witch'},text:'A fortune teller has set a table in the ditch. "Cross my palm, and I will tell you how your next game goes."',choices:[{label:'Cross her palm (15 gold)',cost:{gold:15},charm:'fortune',result:'"You will win it. Probably." Your team seems to believe her.'}]},
 {id:'moth',w:2,who:{name:'Sister Moth, wandering enchanter',kind:'lich'},text:'A wandering enchanter is binding a charm into a fencepost. "The land here is generous. I could draw some off for you."',choices:[{label:'Pay her to draw it (20 gold)',cost:{gold:20},energy:{here:3},result:'She draws the energy up out of the ground and into your jars.'}]},
 {id:'poacher',w:2,who:{name:'Skell, a scalper',kind:'werewolf'},text:'A scalper with a cage on his back, full of stolen team mascots. One of them is crying. "Not your business. Unless you want to buy."',choices:[{label:'Free them: play his crew for it',match:{type:'normal',name:'Skell',win:{gold:40,fans:30},winText:'Skell runs. You open the cage, and the mascots\' clubs send their thanks.'}},{label:'Buy them free (80 gold)',cost:{gold:80},fans:40,result:'The mascots go home. Every club in the league hears who paid.'}]},
 {id:'wisp',w:2,time:'night',who:{scene:'wisp'},text:'Lights move in the grass beside the road, blue and slow, and they seem to want you to follow.',choices:[{label:'Follow the lights',chance:.55,energy:{aether:4},result:'The lights lead you to a hollow full of Aether, and go out.',fail:'The lights go out. Something else was following them.',failMatch:{type:'normal'}}]},
 {id:'thief',w:2,who:{name:'A goblin pickpocket',kind:'goblin'},text:'A goblin darts out from behind your wagon with something in its teeth and is gone before you can grab it.',auto:{steal:1}}];
DB.lore=['a song about Ada Quill, the first champion, and the Voltmite she held at arm\'s length','a song about Gant Vesper\'s three cups and his fourth that got away','a song about the Hatch-Mother and the lighthouse that went dark','a song about the road north of the Roost that goes nowhere','a song about Apex Biologic, sung very quietly'];
/* rare chimera chains */
DB.chars.almond.topics.unlisted={t:'There is one thing in the Bestiary I have never drawn. A moth, big as your hand, pale, that drinks the lamps dry at night. Fenwick swears it is real. Ask him about the MOTH.',need:'q_almond',needNo:'Finish the Bestiary entry first. Then we will talk about the ones nobody has.',set:'rq_lumi1',xp:10};
DB.chars.almond.topics.moth={t:'The moth is Fenwick\'s story. Fenwick Tallow, the lamplighter by the fountain. Ask him, not me; I only draw what I am shown.'};
DB.chars.almond.topics.kinds.t2='Your name is in the frontispiece. Second column, small print. Ask me about the UNLISTED one some time.';
DB.chars.tallow.topics.moth={t:'The lamp moth! Nobody believes me. It comes after dark and drinks the oil and leaves the glass cold. Three aethercaps and I will brew a bait oil it cannot resist, and then we set a TRAP.',need:'rq_lumi1',take:{aethercap:3},once:'rq_lumi2',xp:10,t2:'The bait oil is in the fountain lamp. Come back after dark and ask about the TRAP.',needNo:'Three aethercaps for the bait, and not before Prue has had her say.'};
DB.chars.tallow.topics.trap={t:'Look, there, on the fountain lamp. It came, it laid, and it went. That is an egg, handler, warm as a cup of tea. Take it before Prue sees it and wants to draw it.',need:'rq_lumi2',needNight:1,once:'rq_lumi3',xp:25,t2:'The lamps burn true now. I almost miss it.',needNo:'It only comes after dark, and only to a baited lamp.'}; // dropped: giveEgg lumivore; the once flag marks it for a phase 3 quest companion
DB.chars.marrowbone.topics.last={t:'The last entry. I never wrote it; I could not. Something came up under the Marigold as she went over and carried me to the sand on its back. A serpent, gold on green, young. Ysolde reckons it is the Hatch-Mother\'s kin. Ask her about the SERPENT.',need:'q_shiplog',needNo:'My log is lost with my ship. What would I read you?',set:'rq_serp1',xp:10};
DB.chars.marrowbone.topics.serpent={t:'I only saw its back. Ysolde Wrack knows the deep water. Ask her.'};
DB.chars.marrowbone.topics.log.t2='I read it every night now. All but the LAST entry.';
DB.chars.diver.topics.serpent={t:'A wyrmling, gold on green? They nest under the Hatch-Mother, where it is warm. She would never let you near. Beat her, bring me two salt fish for the swim, and I will go down and look for the CLUTCH.',need:'rq_serp1',needNo:'Serpents? In the fen? Ask the captain; he tells that story when he has had a drink.',set:'rq_serp2',xp:10};
DB.chars.diver.topics.clutch={t:'Found it. One egg left in the clutch, under the old pearl bed. I think it has been waiting. Take it, and tell the captain.',need:['rq_serp2','alpha_hatchmother'],take:{saltfish:2},once:'rq_serp3',xp:25,t2:'Did you tell him? Good.',needNo:'The Hatch-Mother first, then two salt fish, and then I dive.'}; // dropped: giveEgg tidewyrmling; the once flag marks it for a phase 3 quest companion
DB.chars.pyre.topics.pits={t:'The pit champion, before the ban, was a lion with a mane of fire. They bred the line in seam glass: the kits grow inside the glass until it cracks. The last of them died with the pits. Unless somebody has found glass that beats. Ask Grit what is INSIDE his box.',need:'q_pyre',needNo:'Pay my price first. Then I tell stories.',set:'rq_cind1',xp:10};
DB.chars.pyre.topics.inside={t:'I do not know what is in his box. Grit Halloway does. Ask him.'};
DB.chars.pyre.topics.price.t2='Hit them first. Hit them hardest. The rest is paperwork. Ask me about the PITS some time.';
DB.chars.grit.topics.inside={t:'Inside? It cracked last night. I did not want to tell anybody. There is an egg in the box where the heart was, and it is too hot to hold, and it is purring. Take it. Please.',need:['q_glass','rq_cind1'],once:'rq_cind2',xp:25,t2:'The box is empty and it still hums.',needNo:'The box? It is just a box. Why do you ask?'}; // dropped: giveEgg cindermane; the once flag marks it for a phase 3 quest companion
DB.chars.halvard.topics.call={t:'The first bell was not cast to call the Matriarch. It was cast to call her young. Take the abbey tuning rod and strike the old bell in the Frozen Chapel after dark. Something will come down out of the lights. Be ready; it will not stay.',need:'q_clapper',needNo:'Bring the first bell\'s clapper home before you ask me about bells.',give:{tuningrod:1},once:'rq_aur1',xp:15,t2:'Strike the chapel bell after dark, with the rod.'};
DB.chars.halvard.topics.clapper.t2='It rang at dawn. Did you hear? The whole town heard. Ask me what it was cast to CALL.';
DB.chars.pell.topics.capsule={t:'A dormant capsule. Pre-League. Oh, you beautiful thing. Six Aether, straight into the cell, and let us see. ... There. An egg. It grew the shell to hatch from. Put it in the incubator and do not tell the League.',take:{capsule:1},takeEn:{aether:6},once:'rq_vault',xp:25,t2:'I have been reading the capsule for a week. It has a serial number. It has a MANUFACTURER.',needNo:'A capsule? If you ever find one, bring it, and six Aether to wake it. The Gene Vault is where they would be.'}; // dropped: giveEgg vaultling; the once flag marks it for a phase 3 quest companion
DB.chars.pell.topics.manufacturer={t:'Apex. The serial prefix is Apex Biologic. Before the League. Make of that what you like.',need:'rq_vault',needNo:'What manufacturer?'};
// dropped: pell.stitch (takeParts and a patchwork egg) and its parts hook
DB.chars.hermit.topics.elder={t:'Fight it if you must. But leave a berry. It counts. And if you beat it fairly, come back and I will teach your cook the OFFERING.'};
DB.chars.hermit.topics.offering={t:'Two mossberries, a honey drop, an aethercap, baked in a leaf. Your cook knows how now; I have told the wind and the wind will tell her. Bring one here and I will call the grove\'s own DRAKE for you.',need:['q_hermit','alpha_grove'],needNo:'The grove has to know you first. Bring me aethercaps, and beat the Elder fairly.',set:'recipe_offering',xp:10};
DB.chars.hermit.topics.drake={t:'Give it here. ... Listen. There. It came down out of the canopy, took the offering, and left this in the leaves. The Elder\'s own line. Go carefully with it.',take:{offering:1},once:'rq_drake',xp:25,t2:'The grove is quiet and full.',needNo:'An offering first. Your cook will know how, once I have taught it.'}; // dropped: giveEgg bloomdrake; the once flag marks it for a phase 3 quest companion
DB.chars.ingrith.topics.map.t='Five regions, four cups, three vaults, two lairs, one crown. And one road that does not go anywhere, north of the Roost. I drew it. I still do not know why. If you have been to the Roost, ask me about the ROAD.';
DB.chars.ingrith.topics.road={t:'East of the Roost, on the coast, a straight road runs into the snow and stops. There are tracks at the end of it that are there at dawn and gone by noon. Go at night, if you go. Take a friend. Take two.',need:'q_ingrith',needNo:'Survey the Roost for me first. Then we can talk about the places I have not drawn.',set:'clue_den',xp:10};
DB.chars.moss_inn.topics.rot={t:'The log has rot in the north wall. Two twists of salt in the wound and it dries. Bring salt and the honey drops in the cellar are yours.',take:{salt:2},give:{honeydrop:3},once:'q_hollow',xp:10,t2:'The wall is drying. You can hear it creak.',needNo:'Two twists of salt. The chandler in Saltmere, or Merrit.'};
DB.chars.moss_inn.topics.job.t+=' The log has ROT, if you are handy.';
DB.chars.cind_inn.topics.cellar={t:'The cellar goes down into the old workings. If you have been down the Deep Seam and come back, you are welcome to what is on the racks: the jerky the miners left.',need:'seen_deepseam',needNo:'Nobody goes in the cellar until they have been down the Seam. House rule. Ask Grit.',give:{jerky:4},once:'q_annie',xp:10,t2:'The racks are bare now. Good.'};
DB.chars.cind_inn.topics.job.t+=' There is a CELLAR, for those who have earned it.';
DB.chars.rime_shop.topics.cellar={t:'The ice cellar wants three bunches of frost mint hung in it to keep the smell down. Bring them and take hardtack for the road.',take:{frostmint:3},give:{hardtack:3},once:'q_kettil',xp:10,t2:'The cellar smells of mint now. Better.',needNo:'Three frost mint. I sell it, if you are lazy.'};
DB.chars.rime_shop.topics.job.t+=' The ice CELLAR needs seeing to.';
DB.chars.salt_shop.topics.count={t:'The League wants a count of what swims out there. Go down the Drowned Hatchery and describe it and I will give you salt fish from the good barrel.',need:'seen_hatchery',needNo:'You have not been down. I will know if you are guessing.',give:{saltfish:3},once:'q_pella',xp:10,t2:'The count is filed. Thank you.'}; // dropped: needCaught:2; now needs the hatchery seen
DB.chars.salt_shop.topics.job.t+=' I also keep the fen COUNT for the League.';
DB.chars.nell.topics.salt={t:'The sand wants salting before the crown, two twists, or it dusts. Bring me salt and the steward\'s tip is yours.',take:{salt:2},gold:40,once:'q_nell',xp:10,t2:'Salted. It will not dust.',needNo:'Two twists of salt. Any chandler.'};
DB.chars.nell.topics.job.t+=' I could use SALT for the sand.';
/* phase 4: card payouts on quest topics */
DB.chars.brack.topics.honey.cardChoice={pick:3,pool:wSportPool(['golf','jousting'])};
DB.chars.smith.topics.peppers.card='gr_shoulder';
DB.chars.monk.topics.mint.cardChoice={pick:3,rarity:'u'};
/* phase 4: Brother Quill enchants (act 'enchant'), Marrow Tansy cooks (act 'kitchen'), every innkeeper has a MEAL menu
   (act 'meals'), and three vendors sell cards (act 'cards'). w9b-town.js handles the acts. */
DB.chars.quill.topics.job.t='Enchanter. The land has ENERGY in it, a different kind in every biome. I bind it into your plays: say ENCHANT and I will show you. If you will have me, I will JOIN.';
DB.chars.quill.topics.enchant={t:'Bring me energy, any kind, and I will bind it into a card, or drill a play into your players, or put the charge back in your gear.',act:'enchant'};
DB.chars.tansy.topics.job.t='Cook. A team is what it eats. Bring me FORAGE from the bushes out there and I will COOK you a meal for match day. Say JOIN and I will fetch my pots.';
DB.chars.tansy.topics.forage.t='Every region has its own bush: mossberry, ember pepper, brine kelp, frost mint, and aethercap here on the plains. Bushes grow back in a few days. Any inn hearth will do for cooking, and so will my canteen.';
DB.chars.tansy.topics.cook={t:'Sit. What have you brought me?',act:'kitchen'};
for(const id in DB.innMenu){const ch=DB.chars[id];ch.topics.job.t+=' The kitchen does a MEAL for match day.';ch.topics.meal={t:'Here is what the kitchen can do, and the hearth is yours if you would rather cook.',act:'meals'}}
DB.chars.hq_shop.topics.job.t+=' I keep a binder of league CARDS, too.';
DB.chars.netter.topics.job.t+=' There is a crate of league CARDS in the back, if you like.';
DB.chars.smith.topics.job.t+=' I also keep a rack of league CARDS for the teams.';
for(const id in DB.cardShops)DB.chars[id].topics.cards={t:'Have a look. New stock every week.',act:'cards'};
/* flags the engine itself sets; the audit needs to know they are real */
DB.engineFlags=['cups1','cups2','cups3','cups4','cup_moss','cup_salt','cup_cind','cup_rime','champion'];
